param(
  [switch]$StartExpo
)

$ErrorActionPreference = "Stop"

$projectRoot = (Get-Location).Path
$layoutPath = Join-Path $projectRoot "src\app\(tabs)\_layout.tsx"

if (-not (Test-Path -LiteralPath $layoutPath)) {
  $layoutPath = Join-Path $projectRoot "app\(tabs)\_layout.tsx"
}

if (-not (Test-Path -LiteralPath $layoutPath)) {
  throw "Could not find src\app\(tabs)\_layout.tsx or app\(tabs)\_layout.tsx. Run this script from the Expo project root."
}

Write-Host "Fixing: $layoutPath" -ForegroundColor Cyan

$content = Get-Content -LiteralPath $layoutPath -Raw

# Fix malformed JSX generated by the earlier installer.
$content = [regex]::Replace(
  $content,
  '\(\{\{\s*color\s*,\s*focused\s*\}\}\)\s*=>',
  '({ color, focused }) =>'
)

$content = [regex]::Replace(
  $content,
  'name=\{\{\s*focused\s*\?\s*"([^"]+)"\s*:\s*"([^"]+)"\s*\}\}',
  'name={focused ? "$1" : "$2"}'
)

$content = [regex]::Replace(
  $content,
  'color=\{\{\s*color\s*\}\}',
  'color={color}'
)

$content = [regex]::Replace(
  $content,
  'size=\{\{\s*(\d+)\s*\}\}',
  'size={$1}'
)

# Catch variants that include a size argument in the callback.
$content = [regex]::Replace(
  $content,
  '\(\{\{\s*color\s*,\s*focused\s*,\s*size\s*\}\}\)\s*=>',
  '({ color, focused, size }) =>'
)

[System.IO.File]::WriteAllText(
  $layoutPath,
  $content,
  (New-Object System.Text.UTF8Encoding($false))
)

Write-Host "Tabs layout syntax fixed successfully." -ForegroundColor Green
Write-Host "Correct callback format: ({ color, focused }) => (...)" -ForegroundColor DarkGray

if ($StartExpo) {
  Write-Host "`nStarting Expo with cleared cache..." -ForegroundColor Cyan
  & npx expo start --clear
}
